const read = stage => execFileSync('git', ['show', `:${stage}:${path}`], { encoding: 'utf8' });
const oursText = read(2);
const base = JSON.parse(read(1));
const ours = JSON.parse(oursText);
const theirs = JSON.parse(read(3));
const additions = {};
for (const key of new Set([...Object.keys(base), ...Object.keys(ours), ...Object.keys(theirs)])) {
  const b = JSON.stringify(base[key]);
  const o = JSON.stringify(ours[key]);
  const t = JSON.stringify(theirs[key]);
  if (t === b || o === t) continue;
  if (o !== b) throw new Error(`Translation changed differently on both branches: ${key}`);
  if (Object.hasOwn(ours, key)) throw new Error(`Incoming change needs explicit review: ${key}`);
  if (!Object.hasOwn(theirs, key)) throw new Error(`Incoming deletion needs explicit review: ${key}`);
  additions[key] = theirs[key];
}
const entries = JSON.stringify(additions, null, 2).slice(1, -2);
const result = Object.keys(additions).length ? oursText.trimEnd().replace(/\n\}$/, ',' + entries + '\n}') + '\n' : oursText;
JSON.parse(result);
fs.writeFileSync(path, result);
console.log(`Preserved existing translations and appended ${Object.keys(additions).length} incoming keys.`);
